mapper.update:
update ry_rental.ry_rental_platform_operations_risk_event set event_status = 2, resolved_by = #{operator}, resolved_time = now(), resolved_remark = '本次运营检查未再次发现', update_by = #{operator}, update_time = now() where is_delete = 0 and event_status in (0, 1)
and risk_event_key not in
#{riskEventKey}

mapper.select:
select a.article_id, a.category_id, c.category_name, a.article_title as title, a.source_type, a.member_id, a.article_status as status, a.current_version_no, a.pinned, (select count(1) from ry_rental.ry_rental_knowledge_read_record rr where rr.article_id = a.article_id and rr.is_delete = 0) as read_count, date_format(a.create_time, '%Y-%m-%d %H:%i:%s') as create_time, date_format(a.update_time, '%Y-%m-%d %H:%i:%s') as update_time from ry_rental.ry_rental_knowledge_article a left join ry_rental.ry_rental_knowledge_category c on c.category_id = a.category_id and c.is_delete = 0
a.is_delete = 0 and a.source_type = 1 and a.article_title like concat('%', #{query.title}, '%') and a.category_id = #{query.categoryId} and a.article_status = #{query.status}
order by a.pinned desc, a.update_time desc, a.article_id desc
